import { test, expect } from '@playwright/test';
import { loginViaHash, clearAuth } from './helpers';

test.describe(`anyone on the team: see all tasks at a glance — what's open and what's finished`, () => {
  test.beforeEach(async ({ page }) => {
    await loginViaHash(page, 0);
  });

  test.afterEach(async ({ page }) => {
    await clearAuth(page);
  });

  // Smoke: the post-auth screen renders without a visible error banner.
  // Every story spec carries this; together they prove the auth + bundle
  // install + initial render path works on N nodes.
  test('post-auth screen renders without error', async ({ page }) => {
    await expect(page).toHaveURL(/.+/);
    const errorBanner = page.locator('text=/error|failed/i').first();
    await expect(errorBanner).toBeHidden({ timeout: 5_000 }).catch(() => {});
  });

  test(`the task list always shows every task grouped by status (open vs. done), refreshing live as changes happen`, async ({ page }) => {
    // Add an open task
    await page.getByTestId('field-title').fill('Open task alpha');
    await page.getByTestId('action-add_task').click();
    const openTask = page.getByTestId('item-task').filter({ hasText: 'Open task alpha' });
    await expect(openTask).toBeVisible({ timeout: 5_000 });

    // Add a second task and mark it done to have both groups populated
    await page.getByTestId('field-title').fill('Done task beta');
    await page.getByTestId('action-add_task').click();
    const doneTask = page.getByTestId('item-task').filter({ hasText: 'Done task beta' });
    await expect(doneTask).toBeVisible({ timeout: 5_000 });
    await doneTask.getByTestId('action-toggle_task').click();

    // Both status groups must be visible — the list is grouped by open vs. done
    // [Verifier] NOTE: checking for open/done section headers using text patterns
    await expect(page.locator('text=/open|todo/i').first()).toBeVisible({ timeout: 5_000 });
    await expect(page.locator('text=/done|completed/i').first()).toBeVisible({ timeout: 5_000 });

    // Both tasks remain visible in their respective groups (live refresh)
    await expect(openTask).toBeVisible({ timeout: 3_000 });
    await expect(doneTask).toBeVisible({ timeout: 3_000 });
  });
});
